struct App {
  layoutOption: GridLayoutOptions =  {
    regularSize: [1, 1]
  }
  build() {
    Grid(this.scroller, this.layoutOption) {
      LazyForEach(this.albumsDataSource, (item: LazyItem<AlbumDataItem>): void => {
        if ((item != undefined && item != null) && (item.get() != undefined && item.get() != null)) {
          if (item.index === 0) {
